    private static let w21Bonus = "b) Der neue Filialleiter der Bäckerei ist noch nicht vertraut mit den Details des Datenschutzes. Er fragt Sie, was er tun muss, wenn jemand unrechtmäßig Zugang zu den Informationen aus der Datenbank des digitalen Bonusprogramms hätte und die Kundendaten sehen könnte.\nFolgende Informationen findet er in der Datenbank:\nVorname, Nachname, Mailadresse, Kundennummer, Bonuspunkte, Geburtsdatum"

    static let ihkW2021GA1: [ExamCard] = [
        ihkMatch("ihk-ap2-2021w-ga1-1a", .systeme, w21a1L1,
