                 pairs: [("Arbeitsspeicher (RAM)", "ECC, Speicher-RAID"),
                         ("Netzteil", "Mehrere Netzteile an verschiedenen Stromkreisen, USV"),
                         ("CPU-Lüfter", "Redundanter Kühlkreislauf"),
