        wv(19, .nachhaltigkeit, "Bei der Koch-IT GmbH hat der Umweltschutz einen hohen Stellenwert.\nWelche der folgenden Maßnahmen dient nicht dem Umweltschutz?",
           ["Bei Werbemaßnahmen sollen künftig nur noch Hochglanzkataloge verwendet werden.", "Es werden nur noch nachfüllbare Textmarker verwendet.", "Bei Kopiervorgängen wird Recyclingpapier verwendet.", "Bei verkauften Produkten soll (Plastik-)Verpackungsmüll vermieden werden.", "Häufige Bestellungen von Kleinpackungen sollen möglichst nicht mehr durchgeführt werden."],
