        wv(21, .schutz, "In der Koch-IT GmbH ereignet sich ein Arbeitsunfall, eine Mitarbeiterin verbrennt sich dabei.\nWelche der folgenden Verhaltensweisen eines Ersthelfers ist in diesem Fall richtig?",
           ["Brandwunden mit speziellen, keimfreien Verbandpäckchen für Brandwunden bedecken.", "Als Erstmaßnahme die betroffene Stelle erwärmen.", "Brandwunden mit Öl, Salben, Talk oder Ähnlichem bedecken.", "Brandwunden auswaschen und Brandblasen öffnen.", "Den Unfallhergang mit dem Handy fotografieren und die Bilder unverzüglich der Geschäftsleitung zukommen lassen."],
           "Ziffer 2."),
        wvm(22, .recht, "Ulli Mayer, 26 Jahre, will sich nach Abschluss seiner Ausbildung als Fachinformatiker für Daten- und Prozessanalyse auf die folgende Stellenanzeige bewerben:\n[Anzeige als Text: Koch-IT GmbH. Zur Verstärkung unseres Teams stellen wir Sie zum 01.01.2022 ein als\n(1) Fachinformatiker für Daten- und Prozessanalyse.\n(2) Sie sind jung, belastbar und haben ein angenehmes äußeres Erscheinungsbild.\n(3) Wir bieten Ihnen einen gesicherten Arbeitsplatz mit einem attraktiven Gehalt.\n(4) Wir bieten Ihnen Weiterbildungsmöglichkeiten in unserem Unternehmen.\n(5) Wir bieten Ihnen viele Gestaltungsmöglichkeiten in unserem Unternehmen.\n(6) Wir bieten Ihnen diverse Aufstiegsmöglichkeiten in einem hochmotivierten Team.\nWenn Sie die Anforderungen erfüllen, dann senden Sie Ihre aussagekräftigen Bewerbungsunterlagen zur: Koch-IT GmbH, Herr Klaus Peters, Am Designer Platz 8, 22088 Hamburg, E-Mail: k-peters@koch-it.de]\nWelche in der Stellenanzeige bezifferten Positionen verstoßen gegen das Allgemeine Gleichbehandlungsgesetz? (Zwei Positionen)",
            correct: ["Position 1: „Fachinformatiker für Daten- und Prozessanalyse“ (nur männliche Bezeichnung)", "Position 2: „Sie sind jung, belastbar und haben ein angenehmes äußeres Erscheinungsbild.“"],
            wrong: ["Position 3: gesicherter Arbeitsplatz mit attraktivem Gehalt", "Position 4: Weiterbildungsmöglichkeiten", "Position 5: Gestaltungsmöglichkeiten", "Position 6: Aufstiegsmöglichkeiten in einem hochmotivierten Team"],
            "Position 1 (nur männliche Berufsbezeichnung, Benachteiligung wegen des Geschlechts) und Position 2 („jung“, Benachteiligung wegen des Alters) (im Original Ziffern 1 und 2)."),
        wv(23, .recht, "Als Mitarbeiter/-in in Festanstellung bei der Koch-IT GmbH haben Sie ein Programm entwickelt, das mit großem Erfolg verkauft wird.\nWelche der folgenden Aussagen ist richtig?",
           ["Sofern vertraglich nicht anders geregelt, besitzen Sie das Urheberrecht an dem Programm und die Koch-IT GmbH die Verwertungsrechte.", "Als Urheber/-in haben Sie das Recht, die weitere Nutzung Ihres Programmes zu verbieten.", "Sie haben einen Anspruch auf Beteiligung am Erlös aus allen Verkäufen des Programmes.", "Sie als Autor/-in sind persönlich haftend für entstehende Schäden bei den Anwendern bei eventuellen Fehlern des Programmes.", "Als Autor/-in des Programmes können Sie gegenüber der Koch-IT GmbH die Herausgabe des Quelltextes verweigern."],
           "Ziffer 1."),
        wv(24, .ausbildung, "Frau Mevis, Auszubildende bei der Koch-IT GmbH, möchte acht Wochen ihrer Berufsausbildung im Ausland durchführen. In diesem Zusammenhang wurde sie auf den Europass hingewiesen.\nZu welchem der folgenden Zwecke wurde der Europass geschaffen?",
           ["Der Europass ist ein vereinheitlichtes Dokument, das Qualifikationen und Kompetenzen europaweit verständlich und transparent darstellt.", "Der Europass ersetzt die Reisepässe der EU-Mitgliedstaaten bei Auszubildenden.", "Mit dem Europass kann man innerhalb der EU kostenlos Bahn fahren und verreisen, ohne Wartezeiten an den Grenzen zu haben.", "Mit dem Europass kann man innerhalb der EU formlos Unternehmen gründen und Mitarbeiter aus der gesamten EU einstellen.", "Der Europass garantiert die kostenlose medizinische Versorgung innerhalb der EU für Staatsbürger der EU-Mitgliedsstaaten."],
           "Ziffer 2."),
        wv(25, .sicherheit, "Bei der Koch-IT GmbH gab es in den letzten Monaten ein erhöhtes Aufkommen an sogenannten Phishing-Mails.\nAnhand welchem der folgenden Merkmale erkennen Sie Phishing-Mails?",
           ["Phishing-Mails zielen darauf ab, Zugangsdaten zu erbeuten. Deshalb enthalten sie meist einen Link, über den Sie diese eingeben sollen.", "Phishing-Mails werden immer mit Signatur und persönlicher Anrede verschickt.", "Der wirkliche Absender der Mail stimmt allgemein mit dem Anzeigenamen des Absenders überein.", "Phishing-Mails haben nie Anhänge.", "Die Mail wird immer mit dem gesicherten Kommunikationsprotokoll HTTPS übermittelt."],
           "Ziffer 2."),
        wv(26, .sicherheit, "Sie erhalten eine E-Mail mit folgendem Inhalt:\n„Hallo, wir mussten mit großem Bedauern feststellen, dass wir einige Probleme mit unserem System hatten. Aus gegebenem Grund müssen wir Sie bitten, Ihre Mitgliedschaft im Account mit Ihrem Login sowie Ihren Kreditkarten-Daten zu bestätigen. Bitte folgen Sie dem nachfolgenden Link, und füllen Sie die Felder korrekt aus: http://payment.account.com/ Somit sichern Sie sich weiterhin einen uneingeschränkten Zugriff auf Ihr Konto.“\nWelche der folgenden Verhaltensweisen zum Umgang mit dieser Nachricht ist zutreffend?",
           ["Die E-Mail löschen und die IT-Abteilung oder zuständige Stelle benachrichtigen, falls weitere Schritte notwendig sind.", "Den angegebenen Link öffnen und die geforderten Daten zu dem Account und den Zahlungsdaten eingeben.", "Das Mailprogramm sofort beenden und den Rechner neu booten.", "Die E-Mail an alle Kontakte weiterleiten, um auf die Probleme mit dem genannten Account aufmerksam zu machen.", "Die E-Mail ausdrucken und archivieren, falls deren Inhalt später noch gebraucht wird."],
           "Ziffer 4."),
        wv(27, .sicherheit, "Sie besuchen häufig die Webseiten eines Geschäftspartners.\nWelche der folgenden Einschätzungen zur Sicherheit in dieser Situation ist zutreffend?",
           ["Auch bei bekannten und vertrauenswürdigen Webseiten müssen die Standardsicherheitsmaßnahmen beachtet werden.", "Sie besuchen diese Seite sehr häufig und deshalb müssen Sie sich hier keine Sorgen machen.", "Da Ihnen die Seite bekannt ist und seriösen Inhalt hat, kann hier beim Surfen nichts passieren.", "Nur bei Webseiten mit Animationen oder anderen aktiven Inhalten besteht eine Gefahr.", "Nur Webseiten, die Werbung nachladen, sind unsicher."],
           "Ziffer 3."),
        wv(28, .sicherheit, "Im Rahmen einer Geschäftsreise überlegen Sie, ein öffentliches unverschlüsseltes WLAN geschäftlich zu nutzen.\nWelche der folgenden Aussagen zur Nutzung öffentlicher WLAN-Zugänge ist richtig?",
           ["Mithilfe einer VPN-Lösung können alle Dinge in einem offenen WLAN wie im abgesicherten Unternehmensnetz genutzt werden.", "Das E-Mail-Programm kann in jedem Fall benutzt werden, da alle E-Mail-Programme automatisch verschlüsseln.", "Im öffentlichen WLAN kann kein Computernutzer die Daten mitlesen.", "Wird ein WLAN-Zugang z. B. in einem Café zur Verfügung gestellt, kann man davon ausgehen, dass die Betreiber sich ausreichend um die Sicherheit des Netzes kümmern.", "Ein öffentliches WLAN ist nur sicher, wenn zum Einloggen die E-Mail-Adresse angegeben werden muss."],
           "Ziffer 4."),
